using System.Windows;
using System.IO;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace FacialStudio;
public static class Program {
 [STAThread]public static void Main(string[] args){
  bool automatic=args.Length==4&&args[0]=="--auto-jslot-smoke";bool jslot=args.Length==4&&(args[0]=="--jslot-smoke"||args[0]=="--jslot-smoke-confirmed");bool smoke=args.Length==4&&args[0]=="--preview-smoke";
  if(smoke||jslot||automatic)L.SettingsPath=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[3]))!,"smoke-language.json");
  var app=new Application();app.DispatcherUnhandledException+=(_,e)=>{FacePreview.LogImport("Dispatcher",e.Exception);if(e.Exception is OutOfMemoryException){e.Handled=false;return;}MessageBox.Show(L.T("작업을 완료하지 못했습니다. 편집 내용을 저장하고 리소스를 다시 확인해주세요. 기술 정보는 얼굴 불러오기 로그에서 확인할 수 있습니다."),L.T("Facial Studio 오류"));e.Handled=true;};var window=new MainWindow();
  if(jslot)window.Loaded+=async(_,_)=>{try{var result=window.LoadRaceMenuSmoke(args[1],args[2],args[0]=="--jslot-smoke-confirmed");File.WriteAllText(args[3]+".report.json",System.Text.Json.JsonSerializer.Serialize(new{result.Status,result.MorphsApplied,result.SculptVertices,result.Messages,parts=result.Scene.Parts.Select(p=>new{p.Name,vertices=p.Reference.Length,expressions=p.Tri?.Morphs.Count})},new System.Text.Json.JsonSerializerOptions{WriteIndented=true}));await Task.Delay(150);window.UpdateLayout();var image=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using var stream=File.Create(args[3]);encoder.Save(stream);}catch(Exception e){File.WriteAllText(args[3]+".error.txt",e.ToString());Environment.ExitCode=1;}finally{window.CleanForSmoke();window.Close();}};
  if(smoke)window.Loaded+=async(_,_)=>{try{window.LoadPreviewSmoke(args[1],args[2]);await Task.Delay(200);window.UpdateLayout();var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(args[3]))encoder.Save(stream);}catch(Exception error){File.WriteAllText(args[3]+".error.txt",error.ToString());Environment.ExitCode=1;}finally{window.CleanForSmoke();window.Close();}};
  if(automatic){FaceAssets.FaceAssociations.StorePath=args[3]+".associations.json";window.Loaded+=async(_,_)=>{try{bool loaded=await window.LoadAutomaticSmoke(args[1],args[2]);if(!loaded)throw new InvalidDataException("Automatic import failed; see face-import.log");await Task.Delay(100);window.UpdateLayout();var image=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var output=File.Create(args[3]))encoder.Save(output);File.WriteAllText(args[3]+".report.json",System.Text.Json.JsonSerializer.Serialize(new{loaded,parts=window.ImportedScene?.Parts.Count,window.ImportedScene?.JslotPath,window.ImportedScene?.ExportedNifPath,usvfsObserved=window.ImportedScene?.Resources?.UsvfsObserved,pluginOrderVerified=window.ImportedScene?.Resources?.PluginOrderVerified,gameCompared=false,candidateDialogSuppressedForSmoke=true}));}catch(Exception e){File.WriteAllText(args[3]+".error.txt",e.ToString());Environment.ExitCode=1;}finally{window.CleanForSmoke();window.Close();}};}
  app.Run(window);
 }
}
